Algorithm Negativo
  Dimension imagen[4, 4] As Integer;
  For f <- 0 To 3 Do
    For c <- 0 To 3 Do
      Read imagen[f, c];
    EndFor
  EndFor
  For f <- 0 To 3 Do
    Define linea As String <- "";
    For c <- 0 To 3 Do
      linea <- linea + toText(1 - imagen[f, c]);
    EndFor
    Write linea;
  EndFor
EndAlgorithm
